from lib import *
def box(kind,txt=''): return f'<div style="background:#FFEBA8;border:1.5px dashed #9A7D1F;border-radius:12px;position:relative;height:150px;display:flex;align-items:center;justify-content:center;margin-bottom:8px;overflow:hidden"><div style="position:absolute;left:8px;top:8px;background:#1C1B1F;color:#FFC928;border-radius:10px;padding:1px 9px;font-size:9px;font-weight:700">three.js</div>{blob(kind,112)}'+(f'<div style="position:absolute;bottom:6px;font-size:9px;color:#6B6458">{txt}</div>' if txt else '')+'</div>'
def pw(label,val,vis,focus=False):
    return f'<div class="lbl">{label}</div><div class="inp row sp" style="{"border:1.5px solid #1C1B1F;" if focus else ""}height:38px"><span class="row" style="gap:8px"><span style="color:#6B6458">[[lock]]</span><span style="font-weight:{600 if vis else 400};letter-spacing:{0 if vis else 2}px;font-size:{12 if vis else 11}px">{val}</span></span><span class="ic" style="width:28px;height:28px;background:{"#FFC928;border:1.5px solid #1C1B1F" if vis else "#EFE8D6"}">{"[[eye]]" if vis else "[[eyeoff]]"}</span></div>'
def ck(t,ok=True): return f'<div class="row" style="gap:7px;margin:3px 0"><span style="width:15px;height:15px;border-radius:50%;background:{G if ok else "#fff"};border:1.5px solid {G if ok else "#EADFC2"};color:#fff;display:flex;align-items:center;justify-content:center;font-size:9px">{"[[check]]" if ok else ""}</span><span class="t2" style="color:{"#1C1B1F" if ok else "#6B6458"}">{t}</span></div>'
def meter(n,lab,c): return f'<div class="t1" style="color:{c};font-size:10.5px;margin:6px 0 3px">Kekuatan: {lab}</div><div class="row" style="gap:4px">'+''.join(f'<div style="flex:1;height:5px;border-radius:3px;background:{c if i<n else "#EFE8D6"}"></div>' for i in range(4))+'</div>'
HEAD=lambda t,s:f'<div style="padding:6px 2px 8px"><div style="font-weight:700;font-size:15px">{t}</div><div class="t2">{s}</div></div>'
s1=phone('1. Ganti Password Wajib',HEAD('Buat Password Baru','Password sementara dari Admin harus diganti')+box('idle','Password tersembunyi: mata terbuka')+pw('Password baru','•••••••••',False,True)+pw('Konfirmasi password','•••••••••',False)+meter(2,'Sedang',Y)+'<div style="margin:5px 0">'+ck('Minimal 8 karakter')+ck('Ada huruf besar')+ck('Ada angka')+ck('Ada simbol (!@#)',False)+'</div><div class="btn pri">[[check]] Simpan &amp; Lanjut</div>')
s2=phone('2. Password Terlihat',HEAD('Buat Password Baru','Password sementara dari Admin harus diganti')+box('sleep','Tombol mata ditekan: mata menutup')+pw('Password baru','Kelas9H#Bintang7',True,True)+pw('Konfirmasi password','Kelas9H#Bintang7',True)+meter(4,'Kuat',G)+'<div style="margin:5px 0">'+ck('Minimal 8 karakter')+ck('Ada huruf besar')+ck('Ada angka')+ck('Ada simbol (!@#)')+'</div><div class="btn pri">[[check]] Simpan &amp; Lanjut</div>')

HD=lambda n,s='bot kelas': f'<div style="margin:0 -12px;background:#0B6B5B;color:#fff;padding:9px 14px;display:flex;gap:10px;align-items:center;font-size:12px;font-weight:600"><span>[[back]]</span><div style="width:30px;height:30px;border-radius:50%;background:#FFC928;color:#1C1B1F;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:800">IX</div><div>{n}<div style="font-size:9px;font-weight:400">{s}</div></div></div>'
def chat(inner): return HD('IX-H Hub')+f'<div style="margin:0 -12px;background:#EADFC8;height:624px;padding:12px">{inner}</div>'
def L(t,tm): return f'<div style="background:#fff;border-radius:3px 12px 12px 12px;padding:8px 10px;font-size:10.5px;line-height:1.5;max-width:88%;margin-bottom:8px;box-shadow:0 1px 0 rgba(0,0,0,.1)"><b>IX-H Hub</b><br>{t}<div class="t3" style="text-align:right">{tm}</div></div>'
def Rr(t,tm): return f'<div style="background:#D9FDD3;border-radius:12px 3px 12px 12px;padding:8px 10px;font-size:10.5px;line-height:1.5;max-width:70%;margin:0 0 8px auto;box-shadow:0 1px 0 rgba(0,0,0,.1)">{t}<div class="t3" style="text-align:right">{tm} ✓✓</div></div>'
def day(t): return f'<div style="text-align:center;margin:2px 0 10px"><span style="background:#fff;border-radius:8px;padding:2px 10px;font-size:9.5px;color:#6B6458">{t}</span></div>'
def cap(t): return f'<div class="t3" style="text-align:center;margin-top:10px">{t}</div>'

def consent():
    pt=lambda ic,t:f'<div class="row" style="gap:8px;align-items:flex-start;margin:6px 0"><div class="ic" style="width:26px;height:26px;font-size:12px">[[{ic}]]</div><div class="t2" style="color:#1C1B1F;line-height:1.4">{t}</div></div>'
    return HEAD('Pesan kelas lewat WhatsApp','Aturan kelas IX-H • wajib untuk mengaktifkan akun')+'<div class="card"><div class="row sp"><div class="row"><div class="ic">[[phone]]</div><div><div class="t3">Nomor WhatsApp kamu</div><div class="t1" style="font-size:13px">0822-••••-5310</div></div></div><span class="chip cy">Belum terhubung</span></div></div><div class="card" style="padding:6px 12px">'+pt('mail','Bot “IX-H Hub” hanya mengirim <b>tagihan dan pengingat milikmu</b> ke chat pribadi.')+pt('shield','Pengiriman dengan jeda acak; kamu bisa <b>Balas STOP</b> kapan saja, lalu bendahara menagih langsung.')+pt('lock','Nomor hanya terlihat oleh Admin dan Pengurus (bendahara).')+'</div><div class="al ay"><span>[[info]]</span><span>Persetujuan ini <b>wajib</b> dan sudah disepakati wali kelas bersama orang tua.</span></div><div class="row" style="gap:8px;margin:8px 2px"><span style="width:18px;height:18px;border-radius:5px;background:#FFC928;border:2px solid #1C1B1F;display:flex;align-items:center;justify-content:center;font-size:11px;flex:none">[[check]]</span><span class="t2" style="color:#1C1B1F">Saya setuju nomor ini dipakai untuk pesan kelas IX-H.</span></div><div class="btn pri">Setuju &amp; Lanjut</div>'
s3=phone('3. Persetujuan WhatsApp (Wajib)',consent())
def opt(t,on=False): return f'<div style="flex:1;text-align:center;font-size:10.5px;font-weight:{700 if on else 500};padding:9px 4px;border-radius:12px;background:{"#FFF3C4" if on else "#fff"};border:{"2px solid #1C1B1F" if on else "1.2px solid #EADFC2"}">{t}</div>'
s4=phone('4. Hubungkan: Kirim Pesan ke Bot',HEAD('Hubungkan WhatsApp','Kirim satu pesan ke bot agar bendahara bisa mengingatkanmu')
+'<div class="card"><div class="row sp"><div class="row"><div class="ic">[[bot]]</div><div><div class="t1">Bot IX-H Hub</div><div class="t3">0813-••••-6021</div></div></div><span class="chip cg">Online</span></div></div>'
+'<div class="lbl">Pilih kalimat, atau tulis sendiri</div><div class="row" style="gap:6px;margin-bottom:6px">'+opt('Tagihan kas saya',True)+opt('Laporan kas saya')+'</div><div class="row" style="gap:6px">'+opt('Tagihan kas aku')+opt('Laporan kas aku')+'</div>'
+'<div class="t3" style="margin:8px 2px">Kalimat bebas boleh, asal ada kata <b>kas</b> dan <b>saya/aku</b>. Kirim dari nomor 0822-••••-5310.</div>'
+'<div class="btn pri">[[send]] Buka WhatsApp &amp; Kirim</div>'
+'<div class="al ab" style="margin-top:10px"><span>[[spin]]</span><span>Menunggu pesan masuk dari nomormu…</span></div>'
+'<div class="t3" style="text-align:center">Belum berhasil? <b style="color:#2F6FDB">Hubungi Admin</b></div>')
s5=phone('5. WhatsApp: Bot Membalas',chat(day('Rabu, 4 Nov')+Rr('Tagihan kas saya','08.14')+L('Nomor kamu sudah terhubung.<br><br>Tagihan kas IX-H:<br><b>Kas Minggu ke-1 November</b> • Rp6.000<br>Jatuh tempo: Jumat, 6 Nov • <b>Belum lunas</b><br><br>Bayar ke bendahara, lalu balas <b>LUNAS</b> + foto bukti.<br>Balas <b>STOP</b> untuk berhenti.','08.14')+cap('Bot membalas data milik pengirim saja')))
s6=phone('6. Nomor Terhubung',HEAD('Nomor terhubung','Tagihan dan pengingat akan masuk ke chat WhatsApp-mu')+box('smile','Terhubung!')
+'<div class="card"><div class="row sp"><div class="row"><div class="ic">[[phone]]</div><div><div class="t3">Nomor WhatsApp kamu</div><div class="t1" style="font-size:13px">0822-••••-5310</div></div></div><span class="chip cg">Valid</span></div></div>'
+'<div style="margin:6px 0">'+ck('Pesan pertama diterima 08.14')+ck('Nomor sama dengan yang terdaftar')+ck('Tagihan masuk ke chat pribadi')+'</div><div class="btn pri">Lanjut</div>')
def dots(n): return '<div class="row" style="justify-content:center;gap:6px;margin:10px 0">'+''.join(f'<div style="height:7px;width:{22 if i==n else 7}px;border-radius:4px;background:{"#FFC928;border:1.5px solid #1C1B1F" if i==n else "#EADFC2"}"></div>' for i in range(3))+'</div>'
SK='<div style="text-align:right;padding:6px 4px 0;font-size:11px;color:#6B6458;font-weight:600">Lewati</div>'
def intro(lab,kind,t,d,mid,btn,n):
    return phone(lab,SK+box(kind)+f'<div style="text-align:center"><div style="font-weight:700;font-size:15px">{t}</div><div class="t2" style="margin:3px 8px 8px;line-height:1.5">{d}</div></div>{mid}{dots(n)}<div class="btn pri">{btn}</div>')
m5='<div class="card"><div class="row sp"><div><div class="t3">Kehadiranku</div><b style="font-size:15px">27 / 29 hari</b></div><b style="color:#2E9B5A">93%</b></div><div style="height:7px;background:#EFE8D6;border-radius:4px;margin-top:6px"><div style="width:93%;height:100%;background:#2E9B5A;border-radius:4px"></div></div></div>'
m6='<div class="wa"><div class="bub"><b>IX-H Hub</b><br>Halo Citra, ini tagihan kas IX-H: <b>Kas Minggu ke-1 November</b>, Rp6.000. Balas <b>STOP</b> untuk berhenti.</div></div><div class="t3" style="text-align:center;margin-top:5px">Bayar ke bendahara, lalu balas LUNAS + foto bukti</div>'
m7='<div class="card"><div class="row"><div class="ic">[[cal]]</div><div><div class="t1">Jadwal Hari Ini</div><div class="t3">07.00–07.45 Matematika • R. 12</div></div></div></div><div class="card"><div class="row"><div class="ic">[[book]]</div><div><div class="t1">PR Matematika • Hal. 45–47</div><div class="t3">1 hari lagi</div></div></div></div>'
s7=intro('7. Pengenalan 1/3','idle','Lihat kehadiranmu','Pantau absensi dan persentase kehadiranmu kapan saja dari rumah.',m5,'Lanjut',0)
s8=intro('8. Pengenalan 2/3','smile','Tagihan kas lewat WhatsApp','Bot mengirim tagihan pribadi ke nomormu. Ketik “tagihan kas saya” kapan saja untuk cek.',m6,'Lanjut',1)
s9=intro('9. Pengenalan 3/3','smile','Jadwal & tugas selalu siap','Cek jadwal pelajaran dan PR terdekat, lengkap dengan pengingat.',m7,'Mulai',2)
R_=rules(span=2,items=['Login pertama dengan <b>password sementara</b> dari Admin wajib <b>ganti password</b>; layar ini tidak bisa dilewati.','Password tersembunyi: mata blob <b>terbuka</b>. Tombol mata ditekan (terlihat): mata blob <b>menutup</b>. Syarat: min. 8 karakter, huruf besar, angka, simbol.','Persetujuan pesan WhatsApp <b>wajib</b> (aturan kelas yang disepakati wali kelas dan orang tua); tidak ada tombol lewati.','<b>Jabat tangan:</b> siswa mengirim satu pesan berbahasa biasa ke bot: “tagihan kas saya”, “laporan kas saya”, “tagihan kas aku”, atau “laporan kas aku”. Bot mengenali kata <b>kas</b> + <b>saya/aku</b> (tidak peka huruf), bukan kata kaku seperti HALO.','Pesan harus dikirim dari <b>nomor yang terdaftar</b>; bot hanya membalas tagihan dan laporan kas <b>milik pengirim</b>.','Balasan bot berisi data nyata, jadi pesan pertama langsung berguna. Percakapan dua arah juga mengurangi risiko nomor bot diblokir.','Saat pesan diterima, status nomor otomatis <b>Valid</b> (menggantikan tes kirim manual untuk siswa baru). Jika gagal, tersedia <b>Hubungi Admin</b>.','Kalimat yang sama bisa dipakai kapan saja untuk cek tagihan. <b>STOP</b> tetap ada; status Berhenti memberi tanda ke bendahara untuk menagih langsung (lihat 23).','3 layar pengenalan boleh dilewati; selesai masuk ke <b>Dashboard</b> sesuai role. Password hanya bisa direset Admin lewat Kelola Pengguna.'])
render(page('Onboarding & Login Pertama','Ganti password wajib • persetujuan WhatsApp wajib • jabat tangan dengan bot lewat kalimat biasa • 3 layar pengenalan (contoh: Citra Lestari)',[s1,s2,s3,s4,s5,s6,s7,s8,s9,R_]),'/home/claude/w25/25_onboarding.jpg','25_onboarding')
